void ihevcd_sao_shift_ctb(sao_ctxt_t *ps_sao_ctxt)
{
    codec_t *ps_codec = ps_sao_ctxt->ps_codec;
    UWORD8 *pu1_src_luma;
    UWORD8 *pu1_src_chroma;
    WORD32 src_strd;
    WORD32 ctb_size;
    WORD32 log2_ctb_size;
    sps_t *ps_sps;
    sao_t *ps_sao;
    pps_t *ps_pps;
    slice_header_t *ps_slice_hdr, *ps_slice_hdr_base;
